using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
// Scoped geometric AO rebake. Existing mesh, UVs, normals, albedo, normal map,
// metal/rough maps and physics are preserved. Writes the versioned candidate only.
public static class RebirthCamperPloughAORepair
{
 const string Prefab="Assets/REBIRTHPickupRearCornerCandidate_20261021_v1/rebirthCamper80s.prefab";
 const string Folder="Assets/REBIRTHPickupRearCornerCandidate_20261021_v1/PloughAO";
 const string Output="E:/_Haven/shared/REBIRTHStaged/CamperCorrections_20261021/PloughAORepair";
 const int Size=1024,Samples=32;
 static float Cross(Vector2 a,Vector2 b)=>a.x*b.y-a.y*b.x;
 static float AO(Vector3 p,Vector3 n){var x=Vector3.Cross(n,Mathf.Abs(n.y)<.9f?Vector3.up:Vector3.right).normalized;var y=Vector3.Cross(n,x);int hit=0;for(int k=0;k<Samples;k++){float u=(k+.5f)/Samples,a=k*2.39996323f;var d=x*(Mathf.Sqrt(u)*Mathf.Cos(a))+y*(Mathf.Sqrt(u)*Mathf.Sin(a))+n*Mathf.Sqrt(1-u);if(Physics.Raycast(p+n*.003f,d,.30f,1<<29,QueryTriggerInteraction.Ignore))hit++;}return 1-hit/(float)Samples;}
 static string PhysicsSignature(GameObject root){var text=new StringBuilder();foreach(var c in root.GetComponentsInChildren<Collider>(true))text.AppendLine(c.name+EditorJsonUtility.ToJson(c));foreach(var r in root.GetComponentsInChildren<Rigidbody>(true))text.AppendLine(r.name+EditorJsonUtility.ToJson(r));return text.ToString();}
 public static void Run(){Directory.CreateDirectory(Output);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Prefab));root.name="rebirthCamper80s";var target=root.transform.Find("GameObject/M/REBIRTHModPlow").GetComponentInChildren<MeshRenderer>(true);var filter=target.GetComponent<MeshFilter>();var mesh=filter.sharedMesh;var source=target.sharedMaterial;if(source.shader.name!="Standard")throw new Exception("Expected native reviewed Standard material");string physics=PhysicsSignature(root);var sourceColors=source.color;var main=source.mainTexture;var bump=source.GetTexture("_BumpMap");var metal=source.GetTexture("_MetallicGlossMap");
 var probe=new GameObject("Temporary AO bake geometry");probe.layer=29;probe.transform.SetPositionAndRotation(target.transform.position,target.transform.rotation);probe.transform.localScale=target.transform.lossyScale;probe.AddComponent<MeshCollider>().sharedMesh=mesh;Physics.SyncTransforms();bool oldBack=Physics.queriesHitBackfaces;Physics.queriesHitBackfaces=true;
 var v=mesh.vertices;var n=mesh.normals;var uv=mesh.uv;var indices=mesh.triangles;var sum=new float[Size*Size];var count=new ushort[Size*Size];long rays=0;int faces=0;
 try{for(int i=0;i<indices.Length;i+=3){int a=indices[i],b=indices[i+1],c=indices[i+2];var ua=uv[a]*Size;var ub=uv[b]*Size;var uc=uv[c]*Size;float den=Cross(ub-ua,uc-ua);if(Mathf.Abs(den)<1e-8f)continue;int x0=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(ua.x,Mathf.Min(ub.x,uc.x))),0,Size-1),x1=Mathf.Clamp(Mathf.CeilToInt(Mathf.Max(ua.x,Mathf.Max(ub.x,uc.x))),0,Size-1);int y0=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(ua.y,Mathf.Min(ub.y,uc.y))),0,Size-1),y1=Mathf.Clamp(Mathf.CeilToInt(Mathf.Max(ua.y,Mathf.Max(ub.y,uc.y))),0,Size-1);for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){var q=new Vector2(x+.5f,y+.5f)-ua;float wb=Cross(q,uc-ua)/den,wc=Cross(ub-ua,q)/den,wa=1-wb-wc;if(wa<-.00001f||wb<-.00001f||wc<-.00001f)continue;int k=y*Size+x;var point=target.transform.TransformPoint(v[a]*wa+v[b]*wb+v[c]*wc);var normal=target.transform.TransformDirection((n[a]*wa+n[b]*wb+n[c]*wc).normalized);sum[k]+=AO(point,normal);count[k]++;rays+=Samples;}faces++;}}finally{Physics.queriesHitBackfaces=oldBack;Object.DestroyImmediate(probe);}
 var pixels=Enumerable.Repeat(Color.white,Size*Size).ToArray();var filled=new bool[Size*Size];int texels=0;for(int k=0;k<pixels.Length;k++)if(count[k]>0){float value=sum[k]/count[k];pixels[k]=new Color(value,value,value,1);filled[k]=true;texels++;}
 // Nearest populated island padding prevents black unused atlas pixels from
 // bleeding into the rebake's mip levels. Actual contact AO is never clamped.
 for(int pass=0;pass<8;pass++){var next=(Color[])pixels.Clone();var mask=(bool[])filled.Clone();for(int y=0;y<Size;y++)for(int x=0;x<Size;x++){int k=y*Size+x;if(filled[k])continue;foreach(int step in new[]{-1,1,-Size,Size}){int j=k+step;if(j<0||j>=pixels.Length||step==-1&&x==0||step==1&&x==Size-1||!filled[j])continue;next[k]=pixels[j];mask[k]=true;break;}}pixels=next;filled=mask;}
 var texture=new Texture2D(Size,Size,TextureFormat.RGBA32,false,true);texture.SetPixels(pixels);texture.Apply();string png=Folder+"/PloughGeometricAO.png";if(File.Exists(png))throw new Exception("Preserve prior AO candidate; use new versioned folder");File.WriteAllBytes(png,texture.EncodeToPNG());Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(png);var importer=(TextureImporter)AssetImporter.GetAtPath(png);importer.sRGBTexture=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.maxTextureSize=Size;importer.mipmapEnabled=true;importer.filterMode=FilterMode.Bilinear;importer.wrapMode=TextureWrapMode.Clamp;importer.SaveAndReimport();var material=new Material(source){name="Reviewed plough geometric AO"};material.SetTexture("_OcclusionMap",AssetDatabase.LoadAssetAtPath<Texture2D>(png));material.SetFloat("_OcclusionStrength",1);AssetDatabase.CreateAsset(material,Folder+"/PloughGeometricAO.mat");int assigned=0;foreach(var r in root.transform.Find("GameObject/M/REBIRTHModPlow").GetComponentsInChildren<MeshRenderer>(true))if(r.sharedMaterial==source){r.sharedMaterial=material;assigned++;}
 if(filter.sharedMesh!=mesh||physics!=PhysicsSignature(root)||material.color!=sourceColors||material.mainTexture!=main||material.GetTexture("_BumpMap")!=bump||material.GetTexture("_MetallicGlossMap")!=metal)throw new Exception("Scoped material preservation failed");File.Copy(Prefab,Output+"/candidate-before-AO.prefab",true);PrefabUtility.SaveAsPrefabAsset(root,Prefab);AssetDatabase.SaveAssets();File.WriteAllText(Output+"/repair-receipt.txt","PASS plow material receivers="+assigned+"; geometric hemisphere AO rebake, Size="+Size+",Samples="+Samples+",radius=.30m,bias=.003m; coveredTexels="+texels+",UVfaces="+faces+",rays="+rays+";8pxislandpadding.\nPASS original mesh reference/UV/normals unchanged; albedo/normal/metalrough/color references identical; full Collider/Rigidbody serialized signature unchanged. AO strength remains1, Standard lighting unchanged.\nCandidate only; combined bundle/reopen and GPU after-render deferred.\n");Object.DestroyImmediate(root);Debug.Log("PLOUGH_AO_REPAIR_COMPLETE "+Output);
 }
}
